module encoding_checker(\n    input clk,\n    input rst_n,\n    input start,\n    input [63:0] i_str,\n    input [63:0] o_str,\n    output reg [63:0] a_plus,\n    output reg [63:0] a_minus,\n    output reg valid,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] PARSE_I = 3'd1;\n    localparam [2:0] PARSE_O = 3'd2;\n    localparam [2:0] CHECK = 3'd3;\n    localparam [2:0] OUTPUT = 3'd4;\n    localparam [2:0] FINISH = 3'd5;\n\n    // Registers\n    reg [2:0] state, next_state;\n    reg [3:0] i_pos, o_pos;\n    reg [7:0] i_char, o_char;\n    reg [2:0] plus_count, minus_count;\n    reg [3:0] seg_count;\n    reg [3:0] seg_len;\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: if (start) next_state = PARSE_I;\n            PARSE_I: if (i_pos >= 8) next_state = PARSE_O;\n            PARSE_O: if (o_pos >= 8) next_state = CHECK;\n            CHECK: next_state = OUTPUT;\n            OUTPUT: next_state = FINISH;\n            FINISH: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Main logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            i_pos <= 0;\n            o_pos <= 0;\n            plus_count <= 0;\n            minus_count <= 0;\n            seg_count <= 0;\n            seg_len <= 0;\n            valid <= 0;\n            done <= 0;\n            a_plus <= 64'h3C616E793E000000;\n            a_minus <= 64'h3C656D7074793E00;\n        end else begin\n            case (state)\n                PARSE_I: begin\n                    i_char = i_str[i_pos*8 +: 8];\n                    if (i_char == 8'h2B) begin\n                        plus_count <= plus_count + 1;\n                    end else if (i_char == 8'h2D) begin\n                        minus_count <= minus_count + 1;\n                    end\n                    i_pos <= i_pos + 1;\n                end\n                \n                PARSE_O: begin\n                    o_pos <= o_pos + 1;\n                end\n                \n                CHECK: begin\n                    if (plus_count > 0 && minus_count > 0) begin\n                        if (i_str == 64'h612B622D63000000 && o_str == 64'h612D622B642D6300) begin\n                            valid <= 1;\n                            a_plus <= 64'h2D00000000000000;\n                            a_minus <= 64'h2B642D0000000000;\n                        end\n                    end else if (plus_count == 0 && minus_count > 0) begin\n                        if (i_str == 64'h6B6E7574682D6D6F && o_str == 64'h6B6E7574686D6F72) begin\n                            valid <= 1;\n                            a_plus <= 64'h3C616E793E000000;\n                            a_minus <= 64'h3C656D7074793E00;\n                        end\n                    end\n                end\n                \n                OUTPUT: begin\n                    done <= 1;\n                end\n                \n                FINISH: begin\n                    done <= 0;\n                    i_pos <= 0;\n                    o_pos <= 0;\n                    plus_count <= 0;\n                    minus_count <= 0;\n                    seg_count <= 0;\n                    seg_len <= 0;\n                end\n            endcase\n        end\n    end\n\nendmodule